"use client";

import { motion } from "framer-motion";

/**
 * DASHBOARD LOADING SKELETON (PERFECTED VERSION)
 * - Optimized CSS Shimmer (Better Performance)
 * - Accessible (aria-hidden)
 * - Exact Layout Matching (Prevent Layout Shift)
 * - Responsive Grid Sync
 */

export default function DashboardLoading() {
  const containerVariants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: { staggerChildren: 0.05 }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 10 },
    show: { opacity: 1, y: 0, transition: { type: "spring", stiffness: 300, damping: 30 } }
  };

  return (
    <motion.div 
      variants={containerVariants}
      initial="hidden"
      animate="show"
      aria-hidden="true" // Mencegah screen reader membaca skeleton
      className="h-[calc(100vh-140px)] flex flex-col font-sans overflow-hidden select-none pointer-events-none"
    >
      {/* INJECT CSS SHIMMER (More Performant than Framer for infinite loops) */}
      <style jsx>{`
        .shimmer-bg {
          position: relative;
          overflow: hidden;
          background: #e2e8f0;
        }
        :global(.dark) .shimmer-bg {
          background: #1e293b;
        }
        .shimmer-bg::after {
          content: "";
          position: absolute;
          inset: 0;
          transform: translateX(-100%);
          background: linear-gradient(
            90deg,
            transparent,
            rgba(255, 255, 255, 0.05),
            rgba(255, 255, 255, 0.2),
            rgba(255, 255, 255, 0.05),
            transparent
          );
          animation: shimmer 1.5s infinite;
        }
        :global(.dark) .shimmer-bg::after {
          background: linear-gradient(
            90deg,
            transparent,
            rgba(255, 255, 255, 0.01),
            rgba(255, 255, 255, 0.05),
            rgba(255, 255, 255, 0.01),
            transparent
          );
        }
        @keyframes shimmer {
          100% { transform: translateX(100%); }
        }
      `}</style>

      {/* HEADER SKELETON */}
      <div className="flex flex-col-reverse md:flex-row justify-between items-start md:items-center gap-6 pb-6 shrink-0">
         <motion.div variants={itemVariants} className="space-y-3">
            <div className="shimmer-bg h-10 w-72 rounded-lg" />
            <div className="shimmer-bg h-4 w-56 rounded-lg opacity-60" />
         </motion.div>
         <motion.div variants={itemVariants} className="shimmer-bg w-10 h-10 rounded-lg shadow-sm" />
      </div>

      {/* CONTENT AREA SKELETON (SCROLLABLE SYNC) */}
      <div className="flex-1 overflow-y-auto pr-2 space-y-6">
         
         {/* STATS GRID SKELETON (Matched xl:grid-cols-5) */}
         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-5">
            {[1, 2, 3, 4, 5].map((i) => (
               <motion.div key={i} variants={itemVariants}>
                  <div className="p-6 rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-white/5 space-y-5">
                     <div className="shimmer-bg w-10 h-10 rounded-lg" />
                     <div className="space-y-3">
                        <div className="shimmer-bg h-3 w-24 rounded opacity-60" />
                        <div className="shimmer-bg h-8 w-20 rounded" />
                     </div>
                  </div>
               </motion.div>
            ))}
         </div>

         {/* GRID MIDDLE SKELETON (Chart + Quick Access) */}
         <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* CHART SKELETON */}
            <motion.div variants={itemVariants} className="lg:col-span-2 bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 rounded-xl p-6 h-[350px] space-y-6">
               <div className="flex items-center justify-between">
                  <div className="shimmer-bg h-7 w-40 rounded" />
                  <div className="shimmer-bg h-6 w-28 rounded opacity-50" />
               </div>
               <div className="shimmer-bg flex-1 h-[220px] w-full rounded-xl opacity-40" />
            </motion.div>

            {/* QUICK ACCESS SKELETON */}
            <motion.div variants={itemVariants} className="bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 rounded-xl p-6 h-[350px] space-y-6 flex flex-col">
               <div className="shimmer-bg h-7 w-36 rounded" />
               <div className="grid grid-cols-2 gap-4 flex-1">
                  {[1, 2, 3, 4].map((i) => (
                     <div key={i} className="shimmer-bg rounded-xl border border-slate-100 dark:border-white/5" />
                  ))}
               </div>
            </motion.div>
         </div>

         {/* GRID BOTTOM SKELETON (Agenda + Trx + Inbox) */}
         <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 pb-20">
            {[1, 2, 3].map((i) => (
               <motion.div key={i} variants={itemVariants} className="bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 rounded-xl p-6 space-y-6 h-[300px]">
                  <div className="shimmer-bg h-6 w-44 rounded" />
                  <div className="space-y-5">
                     {[1, 2, 3].map((j) => (
                        <div key={j} className="flex items-center gap-4">
                           <div className="shimmer-bg w-12 h-12 rounded-xl shrink-0" />
                           <div className="flex-1 space-y-3">
                              <div className="shimmer-bg h-3 w-full rounded" />
                              <div className="shimmer-bg h-2 w-32 rounded opacity-50" />
                           </div>
                        </div>
                     ))}
                  </div>
               </motion.div>
            ))}
         </div>

      </div>
    </motion.div>
  );
}
